function @damp ($input:number, $const1:number, $const2:number) : number
	return $input  * $const1 * (input_number("dens", 0)+0.35)  / (1 + (input_number("nav", 0) / ($const2*100))^2)


function @squarein ($input:number) : number
	return sign($input) * $input * $input

function @p($set:number, $input:number, $p:number) : number
	return  $p * ($set - $input)
